create table RB_BUS_PASSWORD (PREV_FAILURE_TIMES INT null  ,INTERNAL_KEY INT not null  ,PASSWORD VARCHAR(200) not null  ,CHANGE_IND VARCHAR(20) not null  ,PASSWORD_STATUS VARCHAR(1) not null  ,LAST_UPD_TIMESTAMP VARCHAR(26) not null  ,PASSWORD_EFFECT_DATE TIMESTAMP(3) not null  ,CREATE_TIMESTAMP VARCHAR(26) not null  ,DAY_FAILURE_TIMES INT null  ,FAILURE_TIMES INT not null  ,PWD_TYPE VARCHAR(2) not null  ,PWD_KEY VARCHAR(50) not null  , primary key(INTERNAL_KEY,PWD_TYPE,PWD_KEY));